(()=>{
 const i=ltManager.getAllInstances().find(i=>i.provider==='codex');const a=ltManager.getAdapter(i.id);
 globalThis.ltCodexAdapter=a;globalThis.ltCodexRequests=[];
 const client=a.appServerClient;const original=client.request;
 client.request=function(method,...args){ltCodexRequests.push({at:Date.now(),method});return original.call(this,method,...args);};
 globalThis.ltRestoreCodexRequests=()=>{client.request=original;};
 return {id:i.id,capabilities:a.getContextCapabilities(),config:{model:a.cliConfig.model,reasoningEffort:a.cliConfig.reasoningEffort},contextUsage:i.contextUsage,threadId:a.appServerRuntime?.binding?.threadId,method:typeof original};
})()

(()=>{
 const w=ltManager.warmStart?.warm; if(!w)return {available:false}; const a=w.adapter;
 globalThis.ltWarmWire=[];let buffer='';
 const capture=(chunk)=>{buffer+=String(chunk);let n;while((n=buffer.indexOf('\n'))>=0){const line=buffer.slice(0,n);buffer=buffer.slice(n+1);try{const p=JSON.parse(line);const blocks=p.message?.content;const errors=Array.isArray(blocks)?blocks.filter(b=>b.type==='tool_result').map(b=>({type:b.type,isError:b.is_error,contentLength:typeof b.content==='string'?b.content.length:null,contentType:typeof b.content,denialMatch:typeof b.content==='string'?ltRequire(process.cwd()+'/dist/main/cli/adapters/claude-cli-permission-details.js').isPermissionDenialContent(b.content):null,denial:typeof b.content==='string'&&b.is_error?b.content.replaceAll(process.cwd(),'<checkout>').slice(0,1200):undefined})):[];if(errors.length||p.type==='result')ltWarmWire.push({at:Date.now(),type:p.type,stopReason:p.stop_reason,hasDeferred:!!p.deferred_tool_use,errors});}catch{}}};
 a.process?.stdout?.on('data',capture);globalThis.ltRemoveWarmWire=()=>a.process?.stdout?.off('data',capture);
 return {available:true,provider:w.provider,hookConfigured:!!a.spawnOptions?.permissionHookPath,stdout:!!a.process?.stdout,yolo:a.spawnOptions?.yoloMode};
})()

import {appendFileSync} from 'node:fs';
import assert from 'node:assert/strict';
const target=(await(await fetch('http://127.0.0.1:9735/json/list')).json()).find(t=>t.type==='page');
const ws=new WebSocket(target.webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);
let n=0;const pending=new Map();ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(m.error):p.resolve(m.result);}};
function send(method,params={}){return new Promise((resolve,reject)=>{const id=++n;pending.set(id,{resolve,reject});ws.send(JSON.stringify({id,method,params}));});}
const pause=ms=>new Promise(r=>setTimeout(r,ms));
async function evaluate(expression){const r=await send('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.exceptionDetails)throw r.exceptionDetails;return r.result.value;}
async function key(key,code,keyCode,modifiers=0){await send('Input.dispatchKeyEvent',{type:'keyDown',key,code,windowsVirtualKeyCode:keyCode,modifiers,...(key==='Enter'?{text:'\r',unmodifiedText:'\r'}:{})});await send('Input.dispatchKeyEvent',{type:'keyUp',key,code,windowsVirtualKeyCode:keyCode,modifiers});await pause(100);}
const steps=[];
try{
 await send('Emulation.setFocusEmulationEnabled',{enabled:true});try{await send('Emulation.setPageVisibilityOverride',{visibility:'visible'});}catch{}
 steps.push(await evaluate('({stage:"visibility",hidden:document.hidden,visibility:document.visibilityState})'));
 const opener=await evaluate('(()=>{window.ltOpener=document.querySelector("button.action-btn.terminate");window.ltOpener?.focus();return {found:!!window.ltOpener,label:document.activeElement?.getAttribute("aria-label")};})()');assert.ok(opener.found);steps.push(opener);
 await key('Enter','Enter',13);
 const capture=async(stage)=>{const x=await evaluate('({dialog:!!document.querySelector("[role=dialog]"),activeClass:document.activeElement?.className,activeText:document.activeElement?.textContent?.trim(),inside:!!document.activeElement?.closest("[role=dialog]"),restored:document.activeElement===window.ltOpener})');steps.push({stage,...x});return x;};
 assert.equal((await capture('initial')).activeClass,'confirm-dialog');
 for(const [stage,expected,mod] of [['tab1','Keep running',0],['tab2','Close session',0],['tab3','Keep running',0],['shiftTab','Close session',8]]){await key('Tab','Tab',9,mod);const x=await capture(stage);assert.equal(x.activeText,expected);assert.equal(x.inside,true);}
 await key('Escape','Escape',27);const last=await capture('escape');assert.equal(last.dialog,false);assert.equal(last.restored,true);
 const record={at:new Date().toISOString(),check:'AR-006-focus',passed:true,steps};appendFileSync('_scratch/lt-queue-runtime/evidence/focus-receipt.jsonl',JSON.stringify(record)+'\n');console.log(JSON.stringify(record));
}catch(e){const record={at:new Date().toISOString(),check:'AR-006-focus',passed:false,steps,error:String(e)};appendFileSync('_scratch/lt-queue-runtime/evidence/focus-receipt.jsonl',JSON.stringify(record)+'\n');console.log(JSON.stringify(record));process.exitCode=1;}finally{ws.close();}

(async()=>{
 const a=window.electronAPI;
 const automationBefore=await a.automationList();
 const instances=await a.listInstances();const results=[];
 for(const i of instances.data||[])results.push({id:i.id,result:await a.terminateInstance({instanceId:i.id})});
 const original=window.ltOriginalContextMode?.data;
 if(!original)throw new Error('Missing settings snapshot');
 const restore=await a.setSetting('contextEvidenceModeByProvider',original);
 const actual=await a.getSetting('contextEvidenceModeByProvider');
 return {automationCount:automationBefore.data?.length,results,remaining:(await a.listInstances()).data?.length,restore,settingsMatch:JSON.stringify(actual.data)===JSON.stringify(original),actual:actual.data};
})()

(async()=>{
 ltRestoreCodexRequests?.();ltRemoveWarmWire?.();
 const c=ltCoordinator;
 const warm=ltManager.warmStart;await warm.cleanup();
 const {app}=ltRequire('electron');
 const metrics=app.getAppMetrics().map(m=>({pid:m.pid,type:m.type,name:m.name}));
 return {mainPid:process.pid,processes:metrics,warmRemaining:!!warm.warm,loopStatus:c.getLoop(ltLoopId)?.status};
})()
